<?php
if (session_status() === PHP_SESSION_NONE) session_start();
require_once __DIR__ . '/../koneksi.php';
mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
if (!isset($_SESSION['id_user'], $_SESSION['role']) || !in_array($_SESSION['role'], ['admin','petugas'], true)) { header('Location: ../login.php'); exit; }
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
function h($v){ return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }
function rp($v){ return 'Rp '.number_format((float)$v,0,',','.'); }
$pesan=''; $jenis='success';
if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (!hash_equals($_SESSION['csrf_token'], (string)($_POST['csrf_token'] ?? ''))) { $pesan='Token formulir tidak valid.'; $jenis='danger'; }
  else {
    $aksi=$_POST['aksi'] ?? ''; $id=(int)($_POST['id'] ?? 0);
    try {
      if ($aksi==='setujui_pesanan' || $aksi==='tolak_pesanan') {
        $status=$aksi==='setujui_pesanan'?'disetujui':'ditolak';
        $stmt=mysqli_prepare($koneksi,"UPDATE penyewaan SET status=? WHERE id_penyewaan=? AND status='menunggu'"); mysqli_stmt_bind_param($stmt,'si',$status,$id); mysqli_stmt_execute($stmt);
        $pesan=mysqli_stmt_affected_rows($stmt)?'Status pesanan berhasil diperbarui.':'Pesanan tidak ditemukan atau statusnya sudah berubah.'; mysqli_stmt_close($stmt);
      } elseif ($aksi==='setujui_fitting' || $aksi==='tolak_fitting') {
        $status=$aksi==='setujui_fitting'?'disetujui':'ditolak';
        $stmt=mysqli_prepare($koneksi,"UPDATE janji_fitting SET status=? WHERE id_fitting=? AND status='menunggu'"); mysqli_stmt_bind_param($stmt,'si',$status,$id); mysqli_stmt_execute($stmt);
        $pesan=mysqli_stmt_affected_rows($stmt)?'Status fitting berhasil diperbarui.':'Fitting tidak ditemukan atau sudah diproses.'; mysqli_stmt_close($stmt);
      } elseif ($aksi==='verifikasi_pembayaran' || $aksi==='tolak_pembayaran') {
        $status=$aksi==='verifikasi_pembayaran'?'diverifikasi':'ditolak'; $catatan=trim($_POST['catatan_petugas'] ?? '');
        mysqli_begin_transaction($koneksi);
        $stmt=mysqli_prepare($koneksi,"SELECT pt.id_pembayaran_tahap,pt.id_penyewaan,pt.tahap,pt.status,s.status AS status_order FROM pembayaran_tahap pt JOIN penyewaan s ON s.id_penyewaan=pt.id_penyewaan WHERE pt.id_pembayaran_tahap=? FOR UPDATE"); mysqli_stmt_bind_param($stmt,'i',$id); mysqli_stmt_execute($stmt); $p=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); mysqli_stmt_close($stmt);
        if (!$p || $p['status']==='diverifikasi') throw new RuntimeException('Pembayaran tidak ditemukan atau sudah diverifikasi.');
        if ($status==='diverifikasi') {
          $cek=mysqli_prepare($koneksi,"SELECT status FROM janji_fitting WHERE id_penyewaan=? AND status='disetujui' LIMIT 1"); mysqli_stmt_bind_param($cek,'i',$p['id_penyewaan']); mysqli_stmt_execute($cek); $fit=(bool)mysqli_fetch_assoc(mysqli_stmt_get_result($cek)); mysqli_stmt_close($cek);
          if (!$fit) throw new RuntimeException('Fitting harus disetujui sebelum pembayaran diverifikasi.');
          if ($p['tahap']==='pelunasan') { $dp=mysqli_prepare($koneksi,"SELECT status FROM pembayaran_tahap WHERE id_penyewaan=? AND tahap='dp'"); mysqli_stmt_bind_param($dp,'i',$p['id_penyewaan']); mysqli_stmt_execute($dp); $d=mysqli_fetch_assoc(mysqli_stmt_get_result($dp)); mysqli_stmt_close($dp); if (!$d || $d['status']!=='diverifikasi') throw new RuntimeException('DP harus diverifikasi sebelum pelunasan.'); }
        }
        $uid=(int)$_SESSION['id_user']; $stmt=mysqli_prepare($koneksi,"UPDATE pembayaran_tahap SET status=?,catatan_petugas=?,diverifikasi_oleh=?,tanggal_verifikasi=NOW() WHERE id_pembayaran_tahap=?"); mysqli_stmt_bind_param($stmt,'ssii',$status,$catatan,$uid,$id); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt);
        if ($status==='diverifikasi' && $p['tahap']==='dp') { $u=mysqli_prepare($koneksi,"UPDATE penyewaan SET status='dp_lunas' WHERE id_penyewaan=? AND status IN ('disetujui','dp_lunas')"); mysqli_stmt_bind_param($u,'i',$p['id_penyewaan']); mysqli_stmt_execute($u); mysqli_stmt_close($u); }
        if ($status==='diverifikasi' && $p['tahap']==='pelunasan') { $u=mysqli_prepare($koneksi,"UPDATE penyewaan SET status='siap_diambil' WHERE id_penyewaan=? AND status IN ('disetujui','dp_lunas','siap_diambil')"); mysqli_stmt_bind_param($u,'i',$p['id_penyewaan']); mysqli_stmt_execute($u); mysqli_stmt_close($u); }
        mysqli_commit($koneksi); $pesan=$status==='diverifikasi'?'Pembayaran berhasil diverifikasi.':'Bukti pembayaran ditolak.';
      } elseif ($aksi==='konfirmasi_pengambilan') {
        mysqli_begin_transaction($koneksi);
        $q=mysqli_prepare($koneksi,"SELECT status,stok_dikurangi FROM penyewaan WHERE id_penyewaan=? FOR UPDATE"); mysqli_stmt_bind_param($q,'i',$id); mysqli_stmt_execute($q); $order=mysqli_fetch_assoc(mysqli_stmt_get_result($q)); mysqli_stmt_close($q);
        if (!$order || $order['status']!=='siap_diambil') throw new RuntimeException('Pesanan belum lunas atau tidak siap diambil.');
        if (!(int)$order['stok_dikurangi']) {
          $d=mysqli_prepare($koneksi,"SELECT id_kebaya,jumlah FROM detail_penyewaan WHERE id_penyewaan=?"); mysqli_stmt_bind_param($d,'i',$id); mysqli_stmt_execute($d); $items=mysqli_stmt_get_result($d);
          while($it=mysqli_fetch_assoc($items)) { $u=mysqli_prepare($koneksi,"UPDATE kebaya SET stok=GREATEST(stok-?,0) WHERE id_kebaya=?"); mysqli_stmt_bind_param($u,'ii',$it['jumlah'],$it['id_kebaya']); mysqli_stmt_execute($u); mysqli_stmt_close($u); }
          mysqli_stmt_close($d);
        }
        $u=mysqli_prepare($koneksi,"UPDATE penyewaan SET status='disewa',tanggal_pengambilan=NOW(),stok_dikurangi=1 WHERE id_penyewaan=?"); mysqli_stmt_bind_param($u,'i',$id); mysqli_stmt_execute($u); mysqli_stmt_close($u); mysqli_commit($koneksi); $pesan='Pengambilan dicatat. Status pesanan menjadi disewa.';
      } elseif ($aksi==='konfirmasi_pengembalian') {
        mysqli_begin_transaction($koneksi);
        $q=mysqli_prepare($koneksi,"SELECT status,stok_dikurangi FROM penyewaan WHERE id_penyewaan=? FOR UPDATE"); mysqli_stmt_bind_param($q,'i',$id); mysqli_stmt_execute($q); $order=mysqli_fetch_assoc(mysqli_stmt_get_result($q)); mysqli_stmt_close($q);
        if (!$order || $order['status']!=='disewa') throw new RuntimeException('Hanya pesanan yang sedang disewa yang bisa dikembalikan.');
        if ((int)$order['stok_dikurangi']) {
          $d=mysqli_prepare($koneksi,"SELECT id_kebaya,jumlah FROM detail_penyewaan WHERE id_penyewaan=?"); mysqli_stmt_bind_param($d,'i',$id); mysqli_stmt_execute($d); $items=mysqli_stmt_get_result($d);
          while($it=mysqli_fetch_assoc($items)) { $u=mysqli_prepare($koneksi,"UPDATE kebaya SET stok=stok+? WHERE id_kebaya=?"); mysqli_stmt_bind_param($u,'ii',$it['jumlah'],$it['id_kebaya']); mysqli_stmt_execute($u); mysqli_stmt_close($u); }
          mysqli_stmt_close($d);
        }
        $u=mysqli_prepare($koneksi,"UPDATE penyewaan SET status='selesai',tanggal_pengembalian=NOW(),stok_dikurangi=0 WHERE id_penyewaan=?"); mysqli_stmt_bind_param($u,'i',$id); mysqli_stmt_execute($u); mysqli_stmt_close($u); mysqli_commit($koneksi); $pesan='Pengembalian dicatat. Stok kebaya sudah dikembalikan dan pesanan selesai.';
      }
    } catch (Throwable $e) { if (mysqli_errno($koneksi)) { @mysqli_rollback($koneksi); } else { @mysqli_rollback($koneksi); } $pesan=$e instanceof RuntimeException?$e->getMessage():'Proses gagal. Periksa struktur database dan coba lagi.'; $jenis='danger'; }
  }
}
$orders=[]; $res=mysqli_query($koneksi,"SELECT s.*,u.nama,(SELECT status FROM pembayaran_tahap WHERE id_penyewaan=s.id_penyewaan AND tahap='dp' LIMIT 1) status_dp,(SELECT status FROM pembayaran_tahap WHERE id_penyewaan=s.id_penyewaan AND tahap='pelunasan' LIMIT 1) status_pelunasan,(SELECT id_fitting FROM janji_fitting WHERE id_penyewaan=s.id_penyewaan ORDER BY id_fitting DESC LIMIT 1) id_fitting,(SELECT status FROM janji_fitting WHERE id_penyewaan=s.id_penyewaan ORDER BY id_fitting DESC LIMIT 1) status_fitting FROM penyewaan s JOIN users u ON u.id_user=s.id_user ORDER BY s.id_penyewaan DESC"); while($r=mysqli_fetch_assoc($res))$orders[]=$r;
$fittings=[]; $res=mysqli_query($koneksi,"SELECT jf.*,u.nama,s.kode_penyewaan FROM janji_fitting jf JOIN users u ON u.id_user=jf.id_user LEFT JOIN penyewaan s ON s.id_penyewaan=jf.id_penyewaan ORDER BY jf.id_fitting DESC"); while($r=mysqli_fetch_assoc($res))$fittings[]=$r;
$payments=[]; $res=mysqli_query($koneksi,"SELECT pt.*,s.kode_penyewaan,u.nama FROM pembayaran_tahap pt JOIN penyewaan s ON s.id_penyewaan=pt.id_penyewaan JOIN users u ON u.id_user=s.id_user ORDER BY pt.id_pembayaran_tahap DESC"); while($r=mysqli_fetch_assoc($res))$payments[]=$r;
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kelola Penyewaan - KebayaRent</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><style>body{background:#fff8fb;color:#503b46;font-family:Arial,sans-serif}.navbar{background:#ad416f}.navbar-brand{color:white;font-weight:800}.panel{background:#fff;border:1px solid #f4d1e0;border-radius:16px;padding:20px;margin-bottom:20px;box-shadow:0 5px 18px #8d49610a}.table thead th{background:#fff0f6;color:#ad416f;white-space:nowrap}.btn-pink{background:#d86b98;color:white;border:0}.btn-pink:hover{background:#ad416f;color:white}.small-muted{font-size:.85rem;color:#8b7581}</style></head><body><nav class="navbar navbar-expand px-3 py-3"><div class="container"><a class="navbar-brand" href="index.php">KebayaRent · Alur Penyewaan</a><a class="btn btn-light btn-sm" href="index.php">Kembali ke Admin</a></div></nav><main class="container py-4"><h2 class="fw-bold mb-1">Kelola Penyewaan</h2><p class="text-secondary">Persetujuan pesanan → fitting → DP 50% → pelunasan → pengambilan → pengembalian.</p><?php if($pesan): ?><div class="alert alert-<?=h($jenis)?> alert-dismissible fade show"><?=h($pesan)?><button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif; ?>
<section class="panel"><h4 class="mb-3">1. Persetujuan pesanan</h4><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Kode / Penyewa</th><th>Tanggal sewa</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><b><?=h($o['kode_penyewaan'])?></b><div><?=h($o['nama'])?></div></td><td><?=h($o['tanggal_mulai'])?> – <?=h($o['tanggal_selesai'])?></td><td><?=rp($o['total'])?></td><td><?=h($o['status'])?></td><td><?php if($o['status']==='menunggu'): ?><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=$o['id_penyewaan']?>"><button class="btn btn-sm btn-success" name="aksi" value="setujui_pesanan">Setujui</button><button class="btn btn-sm btn-outline-danger" name="aksi" value="tolak_pesanan">Tolak</button></form><?php else: ?><span class="small-muted">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h4 class="mb-3">2. Persetujuan fitting</h4><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pesanan / Penyewa</th><th>Jadwal</th><th>Catatan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($fittings as $f): ?><tr><td><?=h($f['kode_penyewaan']??'—')?><div><?=h($f['nama'])?></div></td><td><?=h($f['tanggal_fitting'])?> <?=h(substr($f['jam_fitting'],0,5))?></td><td><?=h($f['catatan'])?></td><td><?=h($f['status'])?></td><td><?php if($f['status']==='menunggu'): ?><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=$f['id_fitting']?>"><button class="btn btn-sm btn-success" name="aksi" value="setujui_fitting">Setujui</button><button class="btn btn-sm btn-outline-danger" name="aksi" value="tolak_fitting">Tolak</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h4 class="mb-3">3. Verifikasi DP dan pelunasan</h4><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pesanan / Penyewa</th><th>Tahap</th><th>Jumlah</th><th>Bukti</th><th>Status</th><th>Catatan penolakan</th><th>Aksi</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?=h($p['kode_penyewaan'])?><div><?=h($p['nama'])?></div></td><td><?=h(strtoupper($p['tahap']))?></td><td><?=rp($p['jumlah_bayar'])?></td><td><a target="_blank" rel="noopener" href="../penyewa/<?=h($p['bukti_pembayaran'])?>">Lihat bukti</a></td><td><?=h($p['status'])?></td><td><?php if($p['status']!=='diverifikasi'): ?><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=$p['id_pembayaran_tahap']?>"><input class="form-control form-control-sm" name="catatan_petugas" placeholder="Alasan jika ditolak"></td><td><button class="btn btn-sm btn-success" name="aksi" value="verifikasi_pembayaran">Verifikasi</button> <button class="btn btn-sm btn-outline-danger" name="aksi" value="tolak_pembayaran">Tolak</button></form><?php else: ?>—</td><td>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h4 class="mb-3">4. Pengambilan dan pengembalian</h4><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pesanan / Penyewa</th><th>Status</th><th>DP</th><th>Pelunasan</th><th>Aksi</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=h($o['kode_penyewaan'])?><div><?=h($o['nama'])?></div></td><td><?=h($o['status'])?></td><td><?=h($o['status_dp']??'belum ada')?></td><td><?=h($o['status_pelunasan']??'belum ada')?></td><td><?php if($o['status']==='siap_diambil'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=$o['id_penyewaan']?>"><button class="btn btn-sm btn-pink" name="aksi" value="konfirmasi_pengambilan">Konfirmasi diambil</button></form><?php elseif($o['status']==='disewa'): ?><form method="post" onsubmit="return confirm('Konfirmasi kebaya sudah kembali dan stok akan ditambahkan?')"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=$o['id_penyewaan']?>"><button class="btn btn-sm btn-success" name="aksi" value="konfirmasi_pengembalian">Konfirmasi kembali</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
</main></body></html>
